export const CORRECTION_TAU_S = 0.1;
export const CORRECTION_SNAP_U = 50;

interface Pose { pos: Vec3; quat: Quat; }

export class CorrectionSmoother {
  private posOffset: Vec3 = { x: 0, y: 0, z: 0 };
  private rotOffset: Quat = quatIdentity();

  onCorrection(renderedBefore: Pose, predictedAfter: Pose): void {
    const correction = vecSub(renderedBefore.pos, predictedAfter.pos);
    if (vecLength(correction) > CORRECTION_SNAP_U) {
      // Teleport / respawn / warp: snap (clear) instead of gliding 100+ m.
      this.posOffset = { x: 0, y: 0, z: 0 };
      this.rotOffset = quatIdentity();
      return;
    }
    this.posOffset = vecAdd(this.posOffset, correction);
    // World-space rotation delta renderedBefore · predictedAfter⁻¹, composed
    // ONTO the stored offset — back-to-back corrections accumulate.
    const rotCorrection = quatMultiply(renderedBefore.quat, quatInverse(predictedAfter.quat));
    this.rotOffset = quatNormalize(quatMultiply(rotCorrection, this.rotOffset));
  }

  apply(predicted: Pose, dtSec: number): Pose {
    const f = Math.exp(-Math.max(0, dtSec) / CORRECTION_TAU_S);
    this.posOffset = vecScale(this.posOffset, f);
    this.rotOffset = quatSlerp(quatIdentity(), this.rotOffset, f);
    return {
      pos: vecAdd(predicted.pos, this.posOffset),
      quat: quatNormalize(quatMultiply(this.rotOffset, predicted.quat)),
    };
  }

  reset(): void {
    this.posOffset = { x: 0, y: 0, z: 0 };
    this.rotOffset = quatIdentity();
  }
}
